"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5797],{71576:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CameraBoomController","desc":"Per-frame raycast occlusion layer that prevents the camera from clipping\\nthrough walls. Each render step it casts from the camera focus toward the\\ncamera position and clamps `Player.CameraMaxZoomDistance` to the hit\\ndistance minus a configurable buffer. The max-distance ceiling switches\\nbetween shooting and third-person values in response to\\n`Signals.OnShootingCameraToggled`, and the clamped distance is smoothed\\neach frame to avoid jarring jumps when geometry enters or leaves the path.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/CameraBoomController.client.luau"}}')}}]);